function formatProcess(p){const raw=String(p??'').trim(),parts=raw.split('/');let n,y;if(parts.length===2){n=parts[0].replace(/\D/g,'');y=parts[1]}else{const digits=raw.replace(/\D/g,'');if(digits.length<5||digits.length>10)return raw;n=digits.slice(0,-4);y=digits.slice(-4)}return /^\d{1,6}$/.test(n)&&/^\d{4}$/.test(y)?n.padStart(6,'0').slice(0,3)+'.'+n.padStart(6,'0').slice(3)+'/'+y:raw}
