function drawPolygon(polygons){const svg=$('polygon-svg');if(!polygons.length){svg.outerHTML='<p class="notice">Poligonal não localizada no retrato atual. Consulte o SIGMINE.</p>';return}const pts=polygons.flat(2),cos=Math.cos(pts.reduce((s,p)=>s+p[1],0)/pts.length*Math.PI/180);let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;pts.forEach(p=>{minX=Math.min(minX,p[0]*cos);maxX=Math.max(maxX,p[0]*cos);minY=Math.min(minY,-p[1]);maxY=Math.max(maxY,-p[1])});const width=Math.max(maxX-minX,.00001),height=Math.max(maxY-minY,.00001),scale=Math.min(600/width,275/height),cx=(minX+maxX)/2,cy=(minY+maxY)/2;svg.innerHTML=polygons.map(rings=>'<path fill="#22974644" stroke="#074987" stroke-width="2" vector-effect="non-scaling-stroke" fill-rule="evenodd" d="'+rings.map(ring=>ring.map((p,i)=>(i?'L':'M')+((p[0]*cos-cx)*scale+340).toFixed(2)+','+((-p[1]-cy)*scale+160).toFixed(2)).join('')+'Z').join('')+'"/>').join('');polygonView={x:0,y:0,w:680,h:320};const apply=()=>svg.setAttribute('viewBox',`${polygonView.x} ${polygonView.y} ${polygonView.w} ${polygonView.h}`);const zoom=f=>{polygonView.x+=polygonView.w*(1-f)/2;polygonView.y+=polygonView.h*(1-f)/2;polygonView.w*=f;polygonView.h*=f;apply()};$('zoom-in').onclick=()=>zoom(.75);$('zoom-out').onclick=()=>zoom(1.333333);$('zoom-reset').onclick=()=>{polygonView={x:0,y:0,w:680,h:320};apply()};let drag=null;svg.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,vx:polygonView.x,vy:polygonView.y};svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(!drag)return;polygonView.x=drag.vx-(e.clientX-drag.x)*polygonView.w/svg.clientWidth;polygonView.y=drag.vy-(e.clientY-drag.y)*polygonView.h/svg.clientHeight;apply()};svg.onpointerup=()=>drag=null;svg.onpointercancel=()=>drag=null;apply()}
function showEvents(){const q=fold(eventQuery),es=eventRows.filter(([d,c])=>fold(d+' '+c+' '+(data.events[c]||'')).includes(q));const order=eventDescending?[...es].reverse():es;$('event-count').textContent=num(es.length)+' de '+num(eventRows.length)+' eventos';$('full-events').innerHTML=order.map(([d,c])=>`<div class="event"><time>${esc(d)} · evento ${esc(c)}</time>${esc(data.events[c]||'Descrição não encontrada')}</div>`).join('')||'<p>Nenhum evento corresponde à busca.</p>'}
detail=async function(index,supplied){const r=supplied||filtered[index];if(!r)return;const token=++detailRequest,pr=r.pred,info=(label,value)=>`<div class="detail-item"><span>${label}</span><b>${value}</b></div>`;$('detailbody').innerHTML=`<div class="detail-heading"><h2>${esc(formatProcess(r.p))}</h2><span class="badge ${esc(r.s)}">${esc(r.s)}</span></div><p>${r.r?r.r+'ª rodada · Área '+esc(r.a):'Estoque atual'} · ${esc(r.m)} / ${esc(r.u)}</p><div class="detail-grid">${info('Lance vencedor registrado',r.v?money(r.v):'Sem lance financeiro')}${info('Área informada',dec(Math.abs(r.ha))+' ha')}${info('Substância · retrato atual',esc(r.sub))}${info('Regime',esc(r.reg||'Sem registro'))}</div><h3>Poligonal atual do processo</h3><div class="geometry"><div class="map-tools"><span>SIGMINE · SIRGAS 2000</span><div><button id="zoom-in" aria-label="Ampliar poligonal">+</button><button id="zoom-out" aria-label="Reduzir poligonal">−</button><button id="zoom-reset">Ajustar</button></div></div><svg id="polygon-svg" role="img" aria-label="Poligonal do processo ${esc(formatProcess(r.p))}" viewBox="0 0 680 320"><text x="30" y="150">Carregando poligonal…</text></svg></div><p class="caption">Arraste para deslocar e use +/− para ampliar. Geometria atual, não reconstituição do edital. O resultado “Livre” desta rodada não comprova disponibilidade atual.</p>${pr?`<h3 class="detail-section">Estimativas retrospectivas da 8ª rodada</h3><div class="detail-grid">${info('Probabilidade de arrematação',pct(pr.p))}${info('Lance central, se arrematada',money(pr.value))}${info('Faixa experimental inferior',money(pr.low))}${info('Faixa experimental superior',money(pr.high))}</div><p class="notice">Faixa com dados DIPEM abertos após o leilão. Apenas diagnóstico retrospectivo; cobertura observada de ${pct(data.model.interval.observed_coverage)}. Não é recomendação de lance.</p>`:'<p class="notice">Sem estimativa fora do treino para esta área. Rodadas sociais e canceladas não entram no modelo comercial.</p>'}<h3 class="detail-section">Histórico completo disponível</h3><div class="event-tools"><label style="flex:1">Buscar evento<input id="event-search" type="search" placeholder="Descrição, código ou data"></label><button id="event-order">Mais recentes primeiro ↓</button></div><small id="event-count">Carregando eventos…</small><div class="timeline" id="full-events"></div><p class="caption">Eventos são registros administrativos, não confirmação automática de situação jurídica atual. Informações pessoais em textos livres foram omitidas.</p><h3 class="detail-section">Contexto municipal anterior ao corte</h3><div class="detail-grid">${info('CFEM · três anos',money(r.cf))}${info('DIPEM · três anos',money(r.di))}</div><p class="caption">Somas municipais, não receitas deste processo. Vínculos territoriais atuais; ausência não equivale a zero. DIPEM apenas para análise retrospectiva.</p>`;$('detail').showModal();$('detail').scrollTop=0;enrichDetail(r);eventRows=[];eventQuery='';eventDescending=true;$('event-search').oninput=e=>{eventQuery=e.target.value;showEvents()};$('event-order').onclick=()=>{eventDescending=!eventDescending;$('event-order').textContent=eventDescending?'Mais recentes primeiro ↓':'Mais antigos primeiro ↑';showEvents()};try{const bucket=r.p.slice(0,4);if(!detailCache.has(bucket)){const response=await fetch('details/'+bucket+'.json');if(!response.ok)throw Error('Detalhes indisponíveis');detailCache.set(bucket,await response.json())}if(token!==detailRequest)return;const d=detailCache.get(bucket)[r.p]||{events:[],polygons:[]};eventRows=d.events;drawPolygon(d.polygons);showEvents()}catch(e){if(token!==detailRequest)return;$('event-count').textContent='Não foi possível carregar os detalhes. Feche e abra novamente.';$('polygon-svg').innerHTML='<text x="30" y="150">Poligonal temporariamente indisponível.</text>'}};
function downloadCSV(name,rows){const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,s=>"'"+s).replace(/"/g,'""')+'"';const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
