function sortSmall(th){const table=th.closest('table'),body=table.tBodies[0],index=[...th.parentElement.children].indexOf(th),dir=th.dataset.direction==='asc'?-1:1;th.dataset.direction=dir===1?'asc':'desc';table.querySelectorAll('th').forEach(t=>t.setAttribute('aria-sort',t===th?(dir===1?'ascending':'descending'):'none'));const value=td=>{const s=td.textContent.trim();if(/^(R\$|[0-9])/.test(s)){const n=Number(s.replace(/[^\d,.-]/g,'').replace(/\./g,'').replace(',','.'));if(Number.isFinite(n))return n}return s};[...body.rows].sort((a,b)=>{const x=value(a.cells[index]),y=value(b.cells[index]);return dir*(typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),'pt-BR',{numeric:true}))}).forEach(r=>body.appendChild(r))}
document.addEventListener('click',e=>{const th=e.target.closest('th[tabindex]');if(th)sortSmall(th)});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('th[tabindex]')){e.preventDefault();sortSmall(e.target)}});let enhTimer;new MutationObserver(()=>{clearTimeout(enhTimer);enhTimer=setTimeout(enhanceHeaders,100)}).observe($('main')||document.querySelector('main'),{childList:true,subtree:true});
async function dates(){try{const response=await fetch('freshness.json?t='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error('freshness');const f=await response.json();$('source-dates').innerHTML='<p>Última verificação: '+new Date(f.checked_at).toLocaleString('pt-BR')+'. Extração inicial: 24/09/2026.</p><table><thead><tr><th>Fonte</th><th>Extração utilizada</th><th>Modificação declarada pela origem</th></tr></thead><tbody>'+f.complementary.map(s=>`<tr><td>${esc(s.file)}</td><td>${esc(s.extracted_at||'24/09/2026')}</td><td>${s.last_modified?new Date(s.last_modified).toLocaleString('pt-BR'):'Não informada'}</td></tr>`).join('')+'</tbody></table><p class="caption">Data de modificação do servidor não garante mudança material. A rotina compara conteúdo antes de integrar. Execução diária depende do aplicativo e do computador disponíveis.</p>'}catch(e){$('source-dates').textContent='Extração inicial das bases: 24/09/2026. Verificação automática ainda não registrada.'}}
